contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256[] calldata tokenIds) public payable {
        uint256 n = tokenIds.length;
        require(n > 0, "need at least one token");

        address nft = c.nft();
        address baseToken = c.baseToken();
        require(nft != address(0), "pool not initialized");

        for (uint256 i = 0; i < n; i++) {
            require(tokenIds[i] != 0, "cannot deposit token id 0");
            for (uint256 j = 0; j < i; j++) {
                require(tokenIds[i] != tokenIds[j], "duplicate token id");
            }
        }

        uint256 value = 0;
        if (baseToken == address(0)) {
            value = 0;
        }

        c.deposit{value: value}(tokenIds, 0);

        for (uint256 i = 0; i < n; i++) {
            assert(ERC721(nft).ownerOf(tokenIds[i]) == address(c));
        }
    }
}

