contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 tokenId, uint256 baseTokenAmount) public payable {
        address nft = c.nft();
        address baseToken = c.baseToken();
        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = tokenId;

        require(address(this).balance >= baseTokenAmount, "insufficient balance");
        require(tokenId != 0, "cannot deposit token id 0");

        ERC721(nft).approve(address(c), tokenId);

        uint256 poolBalanceBefore;
        if (baseToken == address(0)) {
            poolBalanceBefore = address(c).balance;
        } else {
            poolBalanceBefore = ERC20(baseToken).balanceOf(address(c));
            if (baseTokenAmount > 0) {
                ERC20(baseToken).approve(address(c), baseTokenAmount);
            }
        }

        bool reverted;
        if (baseToken == address(0)) {
            try c.deposit{value: baseTokenAmount}(tokenIds, baseTokenAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.deposit(tokenIds, baseTokenAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (!reverted) {
            uint256 poolBalanceAfter;
            if (baseToken == address(0)) {
                poolBalanceAfter = address(c).balance;
            } else {
                poolBalanceAfter = ERC20(baseToken).balanceOf(address(c));
            }
            assert(poolBalanceAfter == poolBalanceBefore + baseTokenAmount);
        }
    }
}

