contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address _factory,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties,
        bytes32 _salt,
        uint256[] memory tokenIds,
        uint256 baseTokenAmount
    ) public payable {
        require(address(this).balance >= baseTokenAmount, "insufficient balance");

        Factory f = Factory(_factory);

        address predictedBefore = f.predictPoolDeploymentAddress(_salt);

        (bool ok, bytes memory ret) = _factory.call(
            abi.encodeWithSelector(
                f.create.selector,
                address(0),
                _nft,
                _virtualBaseTokenReserves,
                _virtualNftReserves,
                _changeFee,
                _feeRate,
                _merkleRoot,
                _useStolenNftOracle,
                _payRoyalties,
                _salt,
                tokenIds,
                baseTokenAmount
            )
        );
        require(ok, "create failed");

        address createdPool;
        assembly {
            createdPool := mload(add(ret, 32))
        }

        address predictedAfter = f.predictPoolDeploymentAddress(_salt);

        assert(predictedBefore == createdPool && predictedAfter == createdPool);
    }

    receive() external payable {}
}

